private theorem partial_series_eq_polynomial (b : ℕ → ℂ) (σ t : ℝ) (N : ℕ) :
    (∑ n ∈ Finset.Icc 1 N, LSeries.term b ((σ : ℂ) + t * I) n) =
      dirPoly N (fun m => LSeries.term b (σ : ℂ) ((m : ℕ) + 1)) (-t)

